let budgetQuoteRequestId = 0;
async function runBudgetQuote() {
  const input = $('#budget-quote-input'), resultEl = $('#budget-quote-result'), sourceEl = $('#budget-quote-source'), button = $('#budget-quote-run');
  const budget = Number(input.value);
  if (!Number.isFinite(budget) || budget <= 0) { resultEl.innerHTML = `<p class="daily-empty">${escapeHtml(t('budgetQuoteInvalid'))}</p>`; return; }
  const requestId = ++budgetQuoteRequestId;
  button.disabled = true; resultEl.innerHTML = `<p class="daily-empty">${escapeHtml(t('budgetQuoteLoading'))}</p>`; sourceEl.textContent = '';
  try {
    const data = await fetchJSON(`/api/v1/bem/budget-quote?budget_bnb=${encodeURIComponent(budget)}`);
    if (requestId !== budgetQuoteRequestId) return;
    if (data.status !== 'ok') { resultEl.innerHTML = `<p class="daily-empty">${escapeHtml(data.error || t('budgetQuoteError'))}</p>`; return; }
    const rows = ['TapeOut', 'Behemoth'].map(key => {
      const p = data.processors?.[key] || {};
      if (p.status !== 'ok') return `<div class="budget-quote-card"><h4>${escapeHtml(key)}</h4><p class="daily-empty">${escapeHtml(p.error || t('budgetQuoteError'))}</p></div>`;
      return `<div class="budget-quote-card"><h4>${escapeHtml(key)}<small>P=${escapeHtml(String(p.p))}</small></h4><div class="budget-quote-metrics"><div><b>${escapeHtml(number(p.machines))}</b><span>${escapeHtml(t('budgetQuoteMachines'))}</span></div><div><b>${escapeHtml(decimal(p.cost_bnb, 4))}</b><span>${escapeHtml(t('budgetQuoteCostBnb'))}</span></div><div><b>${escapeHtml(decimal(p.daily_bem, 3))}</b><span>${escapeHtml(t('budgetQuoteDailyBem'))}</span></div></div><p class="budget-quote-book">${escapeHtml(t('budgetQuoteBestAsk'))} NAND ${p.best_nand_price_bnb != null ? decimal(p.best_nand_price_bnb, 5) : '—'} · LATCH ${p.best_latch_price_bnb != null ? decimal(p.best_latch_price_bnb, 5) : '—'} BNB</p></div>`;
    }).join('');
    resultEl.innerHTML = `<div class="budget-quote-grid">${rows}</div>`;
    const observedAt = data.mining_source?.observed_at ? new Date(data.mining_source.observed_at).toLocaleString(locale()) : '—';
    sourceEl.textContent = `${t('budgetQuoteBoundary')} · ${t('bemObserved')} ${observedAt} · task ${data.task_id} (${data.nand_burn_per_machine} NAND + ${data.latch_burn_per_machine} LATCH)`;
  } catch (error) {
    if (requestId !== budgetQuoteRequestId) return;
    resultEl.innerHTML = `<p class="daily-empty">${escapeHtml(t('budgetQuoteError'))}</p>`;
  } finally {
    if (requestId === budgetQuoteRequestId) button.disabled = false;
  }
}

const BEM_PRICE_POLL_MS = 60 * 1000;
let bemPricePollTimer = null, bemPricePollBusy = false;
async function refreshBemPriceCard() {
  if (document.hidden || bemPricePollBusy) return;
  bemPricePollBusy = true;
  try {
    const price = await fetchJSON(`/api/v1/bem/price?refresh=${Date.now()}`);
    state.bemPrice = price;
    renderBemPrice();
  } catch (error) {
    // Keep the last verified rendering visible. Its API-provided stale state and
    // timestamp remain the user-facing truth until the next successful refresh.
    console.warn('BEM price refresh delayed', error);
  } finally { bemPricePollBusy = false; }
}
function startBemPricePolling() {
  if (bemPricePollTimer) clearInterval(bemPricePollTimer);
  bemPricePollTimer = setInterval(() => { void refreshBemPriceCard(); }, BEM_PRICE_POLL_MS);
}
document.addEventListener('visibilitychange', () => { if (!document.hidden) void refreshBemPriceCard(); });
async function loadBemTasks(page=1) { if (state.bemTaskLoading) return; state.bemTaskLoading=true; try { const data=await fetchJSON(`/api/v1/bem/tasks?${bemTaskQuery(page)}`); state.bemTasks=data; state.bemTaskPage=data.page; } finally { state.bemTaskLoading=false; renderBemTasks(); } }

