  $('#segment-chart').innerHTML = rows.map((row,index) => { const value=values[index], share=Number((value * 10000n) / total) / 100, width=state.segmentMode === 'share' ? share : Number((value * 10000n) / max) / 100, label=state.segmentMode === 'share' ? `${decimal(share,1)}% · ${number(value)}` : `${number(value)} · ${decimal(share,1)}%`; return `<div class="segment-row"><div><span>${escapeHtml(row.key)}</span><b>${escapeHtml(label)}</b></div><i><em style="width:${value > 0n ? Math.max(3,width) : 0}%"></em></i></div>`; }).join('') || `<p class="daily-empty">${escapeHtml(t('dailyNoData'))}</p>`;
