function renderLabelDonut() {
  const rows = (state.analytics.segments?.by_completion_band || []).filter(row => Number(row.processor_count || 0) > 0), total = rows.reduce((sum,row) => sum + Number(row.processor_count || 0), 0);
  // Ordinal completion bands take a single-hue light-to-dark ramp (monotonic
  // lightness, one color per band — never cycled). Adjacent-slice legibility is
  // carried by white separator slivers plus the counted legend, since six steps
  // of one hue cannot alone guarantee large pairwise deltas.
  const bandOrder = ['0%','0–1%','1–25%','25–75%','75–99%','100%+'];
  const ramp = ['#d3e2f6','#a6c4ea','#78a2d9','#4f7ec4','#2f5da8','#123f88'];
  const bandColor = key => ramp[Math.max(0, bandOrder.indexOf(key))];
  const gap = 0.45; let cursor = 0;
  const stops = rows.map(row => {
    const share = (Number(row.processor_count || 0) / Math.max(total, 1)) * 100, next = cursor + share;
    const pad = share > 2 * gap + 0.5 ? gap : 0;
    const segment = `#fbfaf6 ${cursor}% ${cursor + pad}%, ${bandColor(row.key)} ${cursor + pad}% ${next - pad}%, #fbfaf6 ${next - pad}% ${next}%`;
    cursor = next; return segment;
  }).join(', ');
  $('#label-donut').innerHTML = total ? `<div class="donut" style="background:conic-gradient(${stops})"><div><b>${escapeHtml(number(total))}</b><span>${escapeHtml(t('kpiProcessors'))}</span></div></div><div class="donut-legend">${rows.map(row => `<span><i style="background:${bandColor(row.key)}"></i>${escapeHtml(row.key)}<b>${escapeHtml(number(row.processor_count))}</b></span>`).join('')}</div>` : `<p class="daily-empty">${escapeHtml(t('dailyNoData'))}</p>`;
}

