function strategyMatches(event) {
  const rule = state.strategy, metric = big(event.metric_value || 0), entity = rule.entity.trim().toLowerCase();
  if (!rule.types.includes(event.event_type)) return false;
  if (event.metric_name === 'mint_delta' && metric < big(rule.min_mint_delta)) return false;
  if (event.metric_name === 'circuit_delta' && Number(event.metric_value || 0) < Number(rule.min_circuit_delta || 0)) return false;
  if (entity && !`${event.name || ''} ${event.processor_address || ''} ${event.creator_address || ''}`.toLowerCase().includes(entity)) return false;
  return true;
}

