function renderGlossary() {
  const grid = document.querySelector('#glossary-grid');
  if (!grid) return;
  const data = state.glossary;
  if (!data || !Array.isArray(data.items)) { grid.innerHTML = `<p class="daily-empty">${escapeHtml(t('glossaryLoading'))}</p>`; return; }
  const q = String(state.glossarySearch || '').trim().toLowerCase();
  // Glossary source content is bilingual (en/zh) only — there is no Arabic,
  // Korean, Japanese, etc. translation of each term. Previously the "zh"
  // secondary subtitle rendered unconditionally whenever the interface
  // wasn't Chinese, so switching to Arabic (or any of the other 9 locales)
  // still showed a Chinese term under every English one. The secondary
  // subtitle must only appear for the two locales it's actually translated
  // for; every other locale gets English alone, with no Chinese fallback.
  const zhFirst = state.lang === 'zh';
  const hasSecondary = state.lang === 'zh' || state.lang === 'en';
  const rows = q ? data.items.filter(item => [item.term_en, item.term_zh, item.def_en, item.def_zh].some(field => String(field).toLowerCase().includes(q))) : data.items;
  grid.innerHTML = rows.length ? rows.map(item => {
    const primaryTerm = zhFirst ? item.term_zh : item.term_en, secondaryTerm = zhFirst ? item.term_en : item.term_zh;
    const definition = zhFirst ? item.def_zh : item.def_en;
    return `<article class="glossary-card"><h4>${escapeHtml(primaryTerm)}${hasSecondary ? `<small>${escapeHtml(secondaryTerm)}</small>` : ''}</h4><p>${escapeHtml(definition)}</p><a href="${escapeHtml(item.evidence_url)}" target="_blank" rel="noreferrer">${escapeHtml(t('glossaryEvidence'))}</a></article>`;
  }).join('') : `<p class="daily-empty">${escapeHtml(t('glossaryEmpty'))}</p>`;
}

