const setLearningNavOpen=open=>{state.learningNavOpen=Boolean(open); learningNavToggle?.setAttribute('aria-expanded',String(state.learningNavOpen)); if(learningNavMenu) learningNavMenu.hidden=!state.learningNavOpen;};
learningNavToggle?.addEventListener('click',()=>setLearningNavOpen(!state.learningNavOpen));
learningNavMenu?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setLearningNavOpen(false)));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.learningNavOpen){setLearningNavOpen(false);learningNavToggle?.focus();}});
document.addEventListener('click',event=>{if(state.learningNavOpen&&!learningNavMenu?.contains(event.target)&&!learningNavToggle?.contains(event.target)) setLearningNavOpen(false);});
$('#apply-strategy').addEventListener('click',()=>applyStrategy()); $('#share-strategy').addEventListener('click',shareStrategy); $('#tools-toggle').addEventListener('click',()=>{state.toolsExpanded=!state.toolsExpanded;renderCuratedEcosystem();});
const officialAssetTabs=[...document.querySelectorAll('[data-official-asset-project]')];
const activateOfficialAssetProject=project=>{ if (!OFFICIAL_ASSET_PROJECTS.includes(project) || project===state.officialAssetProject) return; state.officialAssetProject=project; renderOfficialAssetObservation(); void loadOfficialAssetProject(project); void loadTransistorCandles(); };
officialAssetTabs.forEach((tab,index)=>{ tab.addEventListener('click',()=>activateOfficialAssetProject(tab.dataset.officialAssetProject)); tab.addEventListener('keydown',event=>{ const direction=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:event.key==='Home'?-index:event.key==='End'?officialAssetTabs.length-1-index:0; if (!direction && !['Home','End'].includes(event.key)) return; event.preventDefault(); const target=officialAssetTabs[(index+direction+officialAssetTabs.length)%officialAssetTabs.length]; target.focus(); activateOfficialAssetProject(target.dataset.officialAssetProject); }); });
const transistorCandleAssetTabs=[...document.querySelectorAll('[data-transistor-candle-asset]')];
const activateTransistorCandleAsset=asset=>{ if (!['nand','latch'].includes(asset) || asset===state.transistorCandleAsset) return; state.transistorCandleAsset=asset; renderTransistorCandles(); void loadTransistorCandles(); };
transistorCandleAssetTabs.forEach((tab,index)=>{ tab.addEventListener('click',()=>activateTransistorCandleAsset(tab.dataset.transistorCandleAsset)); tab.addEventListener('keydown',event=>{ const direction=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:event.key==='Home'?-index:event.key==='End'?transistorCandleAssetTabs.length-1-index:0; if (!direction && !['Home','End'].includes(event.key)) return; event.preventDefault(); const target=transistorCandleAssetTabs[(index+direction+transistorCandleAssetTabs.length)%transistorCandleAssetTabs.length]; target.focus(); activateTransistorCandleAsset(target.dataset.transistorCandleAsset); }); });
$('#transistor-candle-interval')?.addEventListener('change',event=>{state.transistorCandleInterval=event.target.value;renderTransistorCandles();void loadTransistorCandles();});
$('#transistor-candle-range')?.addEventListener('change',event=>{state.transistorCandleRange=event.target.value;renderTransistorCandles();void loadTransistorCandles();});
$('#search').addEventListener('input',event=>{state.search=event.target.value;clearTimeout(registrySearchTimer);registrySearchTimer=setTimeout(()=>loadRegistry(1),180);}); $('#completion-filter').addEventListener('change',event=>{state.completion=event.target.value;loadRegistry(1);}); $('#min-circuits').addEventListener('change',event=>{state.minCircuits=Math.max(0,Number(event.target.value||0));loadRegistry(1);}); $('#sort').addEventListener('change',event=>{state.sort=event.target.value;loadRegistry(1);});
const queueLearningRefresh=()=>{clearTimeout(learnFilterTimer);learnFilterTimer=setTimeout(()=>loadLearning(1),120);}; $('#learn-tier').addEventListener('change',event=>{state.learningTier=event.target.value;queueLearningRefresh();}); $('#learn-stage').addEventListener('change',event=>{state.learningStage=event.target.value;queueLearningRefresh();}); $('#learn-language').addEventListener('change',event=>{state.learningLanguage=event.target.value;queueLearningRefresh();}); $('#learn-search').addEventListener('input',event=>{state.learningSearch=event.target.value;clearTimeout(learnSearchTimer);learnSearchTimer=setTimeout(()=>loadLearning(1),220);});
let toolsSearchTimer; $('#tools-tier').addEventListener('change',event=>{state.toolsTier=event.target.value;loadCuratedEcosystem();}); $('#tools-search').addEventListener('input',event=>{state.toolsSearch=event.target.value;clearTimeout(toolsSearchTimer);toolsSearchTimer=setTimeout(()=>loadCuratedEcosystem(),220);});
	$('#registry-reset').addEventListener('click',()=>{state.search='';state.completion='all';state.minCircuits=0;state.sort='circuits';$('#search').value='';$('#completion-filter').value='all';$('#min-circuits').value='0';$('#sort').value='circuits';loadRegistry(1);}); $('#page-prev').addEventListener('click',()=>loadRegistry(Math.max(1,state.registryPage-1))); $('#page-next').addEventListener('click',()=>loadRegistry(state.registryPage+1));
document.querySelectorAll('.copy-endpoint').forEach(button=>button.addEventListener('click',async()=>{const endpoint=`${location.origin}${button.dataset.endpoint}`;try{await navigator.clipboard.writeText(endpoint);button.textContent=t('copied');setTimeout(()=>button.textContent=t('copyEndpoint'),1200);}catch{window.prompt('Copy API endpoint',endpoint);}}));
async function boot() {
  try { await ensureLanguagePack(state.lang); } catch (error) { console.warn('Initial locale load delayed; falling back to English', error); state.lang='en'; }
  const result = await load();
  startBemPricePolling();
  return result;
}
boot().catch(error=>{ $('#updated').textContent=state.lang === 'zh' ? `核心快照暂不可用：${error.message}；正在自动重试` : `Core snapshot temporarily unavailable: ${error.message}; retrying`; setTimeout(()=>boot().catch(retryError=>console.warn('Core snapshot retry delayed',retryError)),5000); });
